import * as fs from 'fs';
import { env } from 'process';

/**
 * Reads ~/.secrets/agents.env (or another specified path) and merges its contents into process.env.
 *
 * - Skips blank lines and comments (lines starting with `#`).
 * - Does NOT override existing environment variables; only adds/updates missing ones.
 */
export function loadSecretsFromEnvFile(filePath: string): void {
  // Ensure the file exists before attempting to read
  if (!fs.existsSync(filePath)) {
    console.warn(`Environment file not found at ${filePath}. Skipping.`); 
    return;
  }

  const lines = fs.readFileSync(filePath, 'utf8').split('\n');

  for (const line of lines) {
    // Trim whitespace and ignore empty or commented lines
    const trimmed = line.trim();
    if (!trimmed || trimmed.startsWith('#')) {
      continue;
    }

    // Split on the first '=' to support values with '=' in them
    const [key, value] = trimmed.split('=', 2);
    if (key && value) {
      // Only set if the key does not already exist
      if (!env.hasOwnProperty(key)) {
        env[key] = value;
      }
    }
  }

  console.log(`Loaded ${Object.keys(env).length - Object.keys(process.env).filter(k => !env[k]).length} variables from ${filePath}.`);
}
